		clock = realClock{}
	}
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: float64(burst),
		clock:  clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available at the current time,
// consuming them if so.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
